def _missingness_table(df: pd.DataFrame) -> pd.DataFrame:
    """Split each column's missing values into two groups.

    * "Absent by design" — the value logically does not exist for that row
      (e.g. launch-phase metrics for unlaunched concepts).
    * "Applicable but missing" — the value should exist but was not collected
      (a genuine data-collection gap).
    """
    rows: list[dict] = []
    for column in df.columns:
        applicable = _applicable(df, column)
        n_applicable = int(applicable.sum())
        n_present = int(df[column].notna().sum())
        n_absent_by_design = int((~applicable).sum())
        n_applicable_missing = int((applicable & df[column].isna()).sum())
        rate = (n_applicable_missing / n_applicable * 100) if n_applicable else 0.0
        rows.append(
            {
                "Column": column,
                "Applicable": n_applicable,
                "Present": n_present,
                "Absent by design": n_absent_by_design,
                "Applicable but missing": n_applicable_missing,
                "% missing": round(rate, 1),
            }
        )
    return pd.DataFrame(rows)

