def _survey_linear_model(df: pd.DataFrame) -> dict:
    """Fit a linear regression of the target on the survey (stated) measures.

    Restricted to launched concepts (the target is launch-phase only), with
    per-model deletion on the predictors and the target.
    """
    launched = df[df["Launched"] == 1]
    sub = data_utilities.drop_missing_rows(launched, SURVEY_MEASURES + [TARGET])

    X = pd.DataFrame(
        {col: pd.to_numeric(sub[col], errors="coerce") for col in SURVEY_MEASURES}
    )
    y = pd.to_numeric(sub[TARGET], errors="coerce")

    model = LinearRegression().fit(X, y)
    n = len(X)
    k = len(SURVEY_MEASURES)
    r2 = float(model.score(X, y))
    adj_r2 = 1 - (1 - r2) * (n - 1) / (n - k - 1)

    coefs = pd.DataFrame(
        [{"Term": "Intercept", "Coefficient": float(model.intercept_)}]
        + [
            {"Term": col, "Coefficient": float(coef)}
            for col, coef in zip(SURVEY_MEASURES, model.coef_)
        ]
    )

